/* XE3AGLE v20 — legacy suite; media uses Firebase shim (local-only) */
import { AuthManager } from './auth/auth-manager.js';
import { SyncManager } from './auth/sync-manager.js';
import { db, storage, ref, getDownloadURL, uploadBytes, listAll, deleteObject, doc, setDoc, getDoc } from './firebase-client.js';
import { migrateState } from './core/migration-manager.js';

const $=id=>document.getElementById(id);
const uid=()=>{try{return crypto.randomUUID()}catch{return 'id-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toast=(m,t='info')=>window.toast?.(m,t);
const state=()=>window.state||{};
const trades=()=>Array.isArray(state().trades)?state().trades:[];
const save=()=>window.saveState?.();
const money=v=>{try{return window.formatCurrency?window.formatCurrency(Number(v)||0,state().settings?.currency||'USD'):(Number(v)||0).toFixed(2)}catch{return (Number(v)||0).toFixed(2)}};
const isoDate=t=>String(t?.closedAt||t?.date||'').slice(0,10);
const dateOf=t=>{const d=new Date(t?.closedAt||`${t?.date||''}T${t?.time||'12:00:00'}`);return Number.isFinite(d.getTime())?d:new Date(0)};
const closed=()=>trades().filter(t=>String(t.tradeType||'').toLowerCase()!=='live' && (t.result||t.closedAt));
const now=()=>new Date();

function style(){
 if($('xe-v16-style'))return;
 const s=document.createElement('style');s.id='xe-v16-style';s.textContent=`
.xe16-card{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:14px;margin-top:12px}.xe16-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.xe16-kpi{background:var(--surface2);border:1px solid var(--border);border-radius:9px;padding:12px}.xe16-kpi b{display:block;font:800 20px/1.2 'SF Mono','Consolas',monospace;margin-top:4px}.xe16-muted{font-size:11px;color:var(--text3)}.xe16-row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.xe16-row>*{max-width:100%}.xe16-table{width:100%;border-collapse:collapse;font-size:12px}.xe16-table th,.xe16-table td{padding:8px;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}.xe16-table th{font-size:10px;color:var(--text3);text-transform:uppercase}.xe16-pill{display:inline-flex;padding:4px 7px;border-radius:999px;background:var(--surface2);border:1px solid var(--border);font-size:10px}.xe16-drop{border:1px dashed var(--border2);background:var(--surface2);border-radius:10px;padding:16px;text-align:center;cursor:pointer}.xe16-drop.drag{outline:2px solid var(--green);background:var(--green-bg)}.xe16-calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}.xe16-cal-head{font-size:9px;color:var(--text3);text-align:center;padding:5px}.xe16-day{min-height:52px;border:1px solid var(--border);border-radius:7px;background:var(--surface2);padding:6px;font-size:10px;cursor:pointer}.xe16-day.muted{opacity:.35}.xe16-day strong{display:block;font-size:11px}.xe16-day .p{font-family:monospace;margin-top:4px}.xe16-day.win .p{color:var(--green)}.xe16-day.loss .p{color:var(--red)}.xe16-chart{width:100%;height:230px;border:1px solid var(--border);border-radius:9px;background:var(--surface2)}.xe16-status{font-size:10px;padding:5px 8px;border:1px solid var(--border);border-radius:999px}.xe16-status.ok{color:var(--green);background:var(--green-bg)}.xe16-status.warn{color:var(--amber);background:var(--amber-bg)}.xe16-status.bad{color:var(--red);background:var(--red-bg)}.xe16-modal{position:fixed;inset:0;z-index:100010;background:rgba(0,0,0,.72);display:flex;align-items:center;justify-content:center;padding:16px}.xe16-modal>div{width:min(760px,100%);max-height:90vh;overflow:auto;background:var(--surface);border:1px solid var(--border2);border-radius:14px;padding:18px}.xe16-modal textarea,.xe16-modal input,.xe16-modal select{width:100%;box-sizing:border-box;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:9px}.xe16-modal label{display:block;font-size:11px;color:var(--text2);margin-top:9px}.xe16-command{position:fixed;inset:0;z-index:100020;background:rgba(0,0,0,.68);display:flex;align-items:flex-start;justify-content:center;padding-top:12vh}.xe16-command>div{width:min(620px,94vw);background:var(--surface);border:1px solid var(--border2);border-radius:12px;padding:12px}.xe16-command input{width:100%;box-sizing:border-box;background:var(--surface2);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:12px}.xe16-command button{display:block;width:100%;text-align:left;background:transparent;color:var(--text);border:0;padding:10px;border-radius:7px;cursor:pointer}.xe16-command button:hover{background:var(--surface2)}
@media(max-width:600px){.xe16-table{min-width:720px}.xe16-calendar{gap:2px}.xe16-day{min-height:46px;padding:4px}.xe16-chart{height:190px}}
`;document.head.appendChild(s);
}
function ensureV16(){
 const s=state();s.v16=s.v16||{};s.v16.reviews=s.v16.reviews||{weekly:[],monthly:[]};s.v16.tags=Array.isArray(s.v16.tags)?s.v16.tags:[];s.v16.media=Array.isArray(s.v16.media)?s.v16.media:[];s.v16.audit=Array.isArray(s.v16.audit)?s.v16.audit:[];s.v16.challenge=s.v16.challenge||{enabled:false,profitTarget:0,trailingDrawdown:0,initialBalance:Number(s.settings?.balance)||0,payouts:[]};s.v16.protection=s.v16.protection||{daily:0,weekly:0,monthly:0,trailing:0};s.v16.deviceId=s.v16.deviceId||('dev-'+uid());s.v16.deviceName=s.v16.deviceName||((typeof navigator!=='undefined'?navigator.platform:'Browser')+' • '+new Date().toLocaleDateString());return s.v16;
}
function audit(action,detail=''){const v=ensureV16();v.audit.push({id:uid(),at:new Date().toISOString(),action:String(action).slice(0,80),detail:String(detail).slice(0,500)});v.audit=v.audit.slice(-1000);state().auditLog=[...(state().auditLog||[]),v.audit.at(-1)].slice(-1000);save();}
function periodStart(kind,d=now()){const x=new Date(d);x.setHours(0,0,0,0);if(kind==='week'){const n=(x.getDay()+6)%7;x.setDate(x.getDate()-n)}if(kind==='month')x.setDate(1);return x}
function periodPL(start){return closed().filter(t=>dateOf(t)>=start).reduce((a,t)=>a+(Number(t.resultPL)||0),0)}
function peakAndBalance(){const start=Number(state().settings?.balance)||0;let bal=start,peak=start,maxDD=0;for(const t of closed().sort((a,b)=>dateOf(a)-dateOf(b))){bal+=Number(t.resultPL)||0;peak=Math.max(peak,bal);maxDD=Math.max(maxDD,peak-bal)}return {balance:bal,peak,maxDD}}
function protection(){
 const v=ensureV16(), s=state(), start=Number(s.settings?.balance)||0, {balance,peak}=peakAndBalance();
 const dayStart=Number(s.dailyStart?.balance)||start;const daily=Math.max(0,dayStart-balance);const weekly=Math.max(0,-periodPL(periodStart('week')));
 const monthly=Math.max(0,-periodPL(periodStart('month')));
 const trailing=Math.max(0,peak-balance);const c=v.challenge||{};const profit=Math.max(0,balance-(Number(c.initialBalance)||start));
 return {daily,weekly,monthly,trailing,profit,balance,peak,limits:{daily:Number(v.protection.daily)||0,weekly:Number(v.protection.weekly)||0,monthly:Number(v.protection.monthly)||0,trailing:Number(c.trailingDrawdown)||Number(v.protection.trailing)||0,profitTarget:c.enabled?(Number(c.profitTarget)||0):0}};
}
function installProtectionGate(){
 if(window.__xe16ProtectionGate)return;const original=window.validateTrade;if(typeof original!=='function')return;window.__xe16ProtectionGate=true;window.validateTrade=function(){const result=original.apply(this,arguments);const p=protection();const add=x=>{if(!result.reasons.includes(x))result.reasons.push(x)};if(p.limits.daily>0&&p.daily>=p.limits.daily)add(`Daily drawdown limit reached: ${money(p.daily)} / ${money(p.limits.daily)}`);if(p.limits.weekly>0&&p.weekly>=p.limits.weekly)add(`Weekly drawdown limit reached: ${money(p.weekly)} / ${money(p.limits.weekly)}`);if(p.limits.monthly>0&&p.monthly>=p.limits.monthly)add(`Monthly drawdown limit reached: ${money(p.monthly)} / ${money(p.limits.monthly)}`);if(p.limits.trailing>0&&p.trailing>=p.limits.trailing)add(`Trailing drawdown limit reached: ${money(p.trailing)} / ${money(p.limits.trailing)}`);if(p.limits.profitTarget>0&&p.profit>=p.limits.profitTarget)add(`Profit target reached: ${money(p.profit)} / ${money(p.limits.profitTarget)}`);result.allowed=result.reasons.length===0;return result};
}
function accountProtectionCard(){
 const settings=$('page-settings');if(!settings||$('xe16-protection'))return;const v=ensureV16(),p=v.protection,c=v.challenge;const card=document.createElement('div');card.id='xe16-protection';card.className='card';card.innerHTML=`<div class="card-title">ACCOUNT PROTECTION</div><div class="xe16-muted">Rules are stored per trading account. Values of 0 disable that limit.</div><div class="field-row col2"><div class="field"><label>Daily drawdown limit</label><input id="xe16-dd-daily" type="number" min="0" step="0.01" value="${p.daily||''}"></div><div class="field"><label>Weekly drawdown limit</label><input id="xe16-dd-weekly" type="number" min="0" step="0.01" value="${p.weekly||''}"></div><div class="field"><label>Monthly drawdown limit</label><input id="xe16-dd-monthly" type="number" min="0" step="0.01" value="${p.monthly||''}"></div><div class="field"><label>Trailing drawdown limit</label><input id="xe16-dd-trailing" type="number" min="0" step="0.01" value="${c.trailingDrawdown||p.trailing||''}"></div></div><div class="field-row col2"><div class="field"><label>Funding challenge enabled</label><select id="xe16-challenge-enabled"><option value="false">No</option><option value="true" ${c.enabled?'selected':''}>Yes</option></select></div><div class="field"><label>Initial challenge balance</label><input id="xe16-challenge-initial" type="number" min="0" step="0.01" value="${c.initialBalance||state().settings?.balance||0}"></div><div class="field"><label>Profit target</label><input id="xe16-profit-target" type="number" min="0" step="0.01" value="${c.profitTarget||''}"></div></div><div class="xe16-row mt8"><button class="btn btn-primary btn-sm" id="xe16-save-protection">Save protection rules</button><span id="xe16-protection-state" class="xe16-status ok">Protected</span></div><div id="xe16-protection-summary" class="xe16-grid mt12"></div><div class="xe16-row mt12"><button class="btn btn-sm" id="xe16-add-payout">+ Record payout</button></div><div id="xe16-payouts" class="mt8"></div>`;settings.prepend(card);
 const render=()=>{const q=protection();$('xe16-protection-summary').innerHTML=[['Balance',money(q.balance)],['Peak',money(q.peak)],['Daily DD',money(q.daily)],['Weekly DD',money(q.weekly)],['Monthly DD',money(q.monthly)],['Trailing DD',money(q.trailing)],['Challenge P/L',money(q.profit)]].map(([a,b])=>`<div class="xe16-kpi"><span class="xe16-muted">${a}</span><b>${esc(b)}</b></div>`).join('');const bad=(q.limits.daily&&q.daily>=q.limits.daily)||(q.limits.weekly&&q.weekly>=q.limits.weekly)||(q.limits.monthly&&q.monthly>=q.limits.monthly)||(q.limits.trailing&&q.trailing>=q.limits.trailing);$('xe16-protection-state').className='xe16-status '+(bad?'bad':'ok');$('xe16-protection-state').textContent=bad?'LIMIT REACHED':'Protected';$('xe16-payouts').innerHTML=(v.challenge.payouts||[]).slice().reverse().map(x=>`<span class="xe16-pill">${esc(x.date)} • ${money(x.amount)}${x.note?' • '+esc(x.note):''}</span>`).join(' ')||'<span class="xe16-muted">No payouts recorded.</span>'};
 $('xe16-save-protection').onclick=()=>{v.protection.daily=Math.max(0,Number($('xe16-dd-daily').value)||0);v.protection.weekly=Math.max(0,Number($('xe16-dd-weekly').value)||0);v.protection.monthly=Math.max(0,Number($('xe16-dd-monthly').value)||0);v.protection.trailing=Math.max(0,Number($('xe16-dd-trailing').value)||0);v.challenge.enabled=$('xe16-challenge-enabled').value==='true';v.challenge.initialBalance=Math.max(0,Number($('xe16-challenge-initial').value)||0);v.challenge.profitTarget=Math.max(0,Number($('xe16-profit-target').value)||0);v.challenge.trailingDrawdown=v.protection.trailing;audit('ACCOUNT_PROTECTION_UPDATED',JSON.stringify(v.protection));toast('Account protection updated.','success');render();};
 $('xe16-add-payout').onclick=()=>openDialog('Record payout',`<label>Amount<input id="xe16-payout-amount" type="number" min="0" step="0.01"></label><label>Date<input id="xe16-payout-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Note<input id="xe16-payout-note" maxlength="120"></label>`,()=>{const amount=Number($('xe16-payout-amount').value);if(!(amount>0))return toast('Enter a valid payout amount.','error');v.challenge.payouts.push({id:uid(),amount,date:$('xe16-payout-date').value,note:$('xe16-payout-note').value.trim()});audit('PAYOUT_RECORDED',String(amount));save();render();});
 render();
}
function securityCard(){
 const settings=$('page-settings');if(!settings||$('xe16-security'))return;const card=document.createElement('div');card.id='xe16-security';card.className='card';card.innerHTML=`<div class="card-title">ACCOUNT & SECURITY</div><div class="xe16-row"><span id="xe16-email-state" class="xe16-status">Checking…</span><button class="btn btn-sm" id="xe16-verify">Send verification email</button><button class="btn btn-sm" id="xe16-export-personal">Export all personal data</button></div><div class="field-row col2 mt12"><div class="field"><label>Current password (email accounts)</label><input id="xe16-current-password" type="password" autocomplete="current-password"></div><div class="field"><label>New password</label><input id="xe16-new-password" type="password" minlength="6" autocomplete="new-password"></div></div><button class="btn btn-sm" id="xe16-change-password">Change password</button><div class="field-row col2 mt12"><div class="field"><label>New email</label><input id="xe16-new-email" type="email" autocomplete="email"></div><div class="field"><label>Password for re-authentication</label><input id="xe16-email-password" type="password"></div></div><button class="btn btn-sm" id="xe16-change-email">Change email</button><div class="xe16-muted mt12">Account deletion removes cloud account data first, then the XE3AGLE account. Recent authentication may be required by Firebase.</div>`;settings.prepend(card);
 const u=AuthManager.currentUser;const update=()=>{$('xe16-email-state').className='xe16-status '+(u?.emailVerified?'ok':'warn');$('xe16-email-state').textContent=u?.emailVerified?'Email verified':'Email not verified'};update();
 $('xe16-verify').onclick=async()=>{try{await AuthManager.verifyEmail();toast('Verification email sent.','success')}catch(e){toast(e?.message||'Could not send verification email.','error')}};
 $('xe16-change-password').onclick=async()=>{try{await AuthManager.changePassword($('xe16-new-password').value,$('xe16-current-password').value);$('xe16-new-password').value='';toast('Password changed.','success')}catch(e){toast(e?.message==='REAUTH_REQUIRED'?'Current password is required.':e?.message||'Password change failed.','error')}};
 $('xe16-change-email').onclick=async()=>{try{const email=$('xe16-new-email').value.trim();if(!email)return toast('Enter a new email.','error');await AuthManager.changeEmail(email,$('xe16-email-password').value);toast('Email changed. Check your inbox if verification is required.','success')}catch(e){toast(e?.message==='REAUTH_REQUIRED'?'Password is required for email change.':e?.message||'Email change failed.','error')}};
 $('xe16-export-personal').onclick=async()=>{try{const data=await SyncManager.exportPersonalData(AuthManager.currentUser);download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'xe3agle-personal-data.json');audit('PERSONAL_DATA_EXPORTED');toast('Personal data exported.','success')}catch(e){toast('Personal-data export failed.','error')}};
}
async function deleteAllCloud(){
 const u=AuthManager.currentUser;if(!u)throw new Error('NOT_AUTHENTICATED');
 await SyncManager.deleteAllUserData(u);
 if(storage){const root=ref(storage,`users/${u.uid}`);try{const walk=async r=>{const x=await listAll(r);for(const f of x.items)await deleteObject(f).catch(()=>{});for(const d of x.prefixes)await walk(d)};await walk(root)}catch{}}
 await AuthManager.deleteAccount();
}

function deviceCard(){
 const settings=$('page-settings');if(!settings||$('xe16-devices'))return;const card=document.createElement('div');card.id='xe16-devices';card.className='card';card.innerHTML=`<div class="card-title">DEVICES & SESSIONS</div><div class="xe16-muted mb8">Your XE3AGLE API keeps account sessions. Device management is local in this release.</div><div id="xe16-device-list">Loading…</div>`;settings.appendChild(card);const render=async()=>{const list=await SyncManager.listDevices(AuthManager.currentUser);$('xe16-device-list').innerHTML=list.map(d=>`<div class="xe16-row" style="padding:8px 0;border-bottom:1px solid var(--border)"><div style="flex:1"><strong>${esc(d.name||'Browser')}</strong><div class="xe16-muted">${esc(d.platform||'')} • ${esc(d.lastSeenAt?.toDate?d.lastSeenAt.toDate().toLocaleString():String(d.lastSeenAt||''))}</div></div><span class="xe16-pill">${d.id===ensureV16().deviceId?'CURRENT':'KNOWN'}</span>${d.id!==ensureV16().deviceId?`<button class="btn btn-sm btn-danger" data-revoke-device="${esc(d.id)}">Revoke</button>`:''}</div>`).join('')||'<div class="xe16-muted">No device records yet.</div>';document.querySelectorAll('[data-revoke-device]').forEach(b=>b.onclick=async()=>{await SyncManager.revokeDevice(AuthManager.currentUser,b.dataset.revokeDevice);audit('DEVICE_REVOKED',b.dataset.revokeDevice);toast('Device record revoked.','success');render()})};render();
}
function dataCenter(){
 const settings=$('page-settings');if(!settings||$('xe16-data'))return;const card=document.createElement('div');card.id='xe16-data';card.className='card';card.innerHTML=`<div class="card-title">DATA CENTER</div><div class="xe16-row"><button class="btn btn-sm" id="xe16-export-json">JSON backup</button><button class="btn btn-sm" id="xe16-export-csv">CSV export</button><button class="btn btn-sm" id="xe16-export-xlsx">XLSX export</button><button class="btn btn-sm" id="xe16-media-manifest">Media manifest</button><button class="btn btn-sm" id="xe16-media-backup">Media ZIP backup</button><label class="btn btn-sm" for="xe16-import-file" style="cursor:pointer">Import JSON/CSV/XLSX</label><input id="xe16-import-file" type="file" accept=".json,.csv,.xlsx,.xls" hidden></div><div id="xe16-import-preview" class="mt12"></div>`;settings.appendChild(card);
 $('xe16-export-json').onclick=()=>{const payload={product:'XE3AGLE',schemaVersion:16,exportedAt:new Date().toISOString(),account:state().accountMeta,state:structuredClone(state())};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),'xe3agle-backup-v16.json');audit('JSON_BACKUP_EXPORTED')};
 $('xe16-export-csv').onclick=()=>{const fields=['id','date','time','direction','entry','sl','tp','rr','riskPct','riskAmount','positionSize','setup','session','instrument','result','resultR','resultPL','emotion','discipline','tags','violations','notes'];const q=closed();const cell=v=>'"'+String(Array.isArray(v)?v.join('|'):v??'').replaceAll('"','""')+'"';download(new Blob([[fields.join(','),...q.map(t=>fields.map(f=>cell(t[f])).join(','))].join('\n')],{type:'text/csv'}),'xe3agle-v16-trades.csv');audit('CSV_EXPORTED')};
 $('xe16-export-xlsx').onclick=async()=>{if(window.XE3AGLE_PRODUCTION?.exportXLSX){await window.XE3AGLE_PRODUCTION.exportXLSX();audit('XLSX_EXPORTED')}else toast('XLSX exporter unavailable.','error')};
 $('xe16-media-manifest').onclick=()=>{const media=collectMedia();download(new Blob([JSON.stringify({exportedAt:new Date().toISOString(),media},null,2)],{type:'application/json'}),'xe3agle-media-manifest.json');audit('MEDIA_MANIFEST_EXPORTED')};
 $('xe16-media-backup').onclick=backupMediaZip;
 $('xe16-import-file').onchange=async e=>{const file=e.target.files?.[0];if(file)await previewImport(file)};
}
function collectMedia(){const out=[];for(const t of trades()){const shots=t.screenshots||{};for(const [stage,url] of Object.entries(shots)){if(url)out.push({tradeId:t.id,stage,url})}if(t.screenshotCloudUrl)out.push({tradeId:t.id,stage:'cloud',url:t.screenshotCloudUrl})}return [...new Map(out.map(x=>[x.url+'|'+x.stage,x])).values()]}
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++;continue}if(c==='"'){quote=!quote;continue}if(c===','&&!quote){row.push(cell);cell='';continue}if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>x!==''))rows.push(row);row=[];continue}cell+=c}row.push(cell);if(row.some(x=>x!==''))rows.push(row);if(!rows.length)return[];const headers=rows[0].map(x=>x.trim());return rows.slice(1).map(r=>Object.fromEntries(headers.map((h,i)=>[h,r[i]??''])))}
async function loadJSZip(){if(window.JSZip)return window.JSZip;const id='xe16-jszip';if($(id))return new Promise(r=>$(id).addEventListener('load',()=>r(window.JSZip),{once:true}));return new Promise(r=>{const s=document.createElement('script');s.id=id;s.src='https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js';s.onload=()=>r(window.JSZip);s.onerror=()=>r(null);document.head.appendChild(s)})}
async function backupMediaZip(){const media=collectMedia();if(!media.length)return toast('No cloud screenshots found.','info');const Zip=await loadJSZip();if(!Zip)return toast('ZIP library unavailable. Use the media manifest instead.','error');const zip=new Zip();let added=0;for(const item of media){try{const r=await fetch(item.url,{mode:'cors'});if(!r.ok)continue;const blob=await r.blob();zip.file(`${item.tradeId}/${item.stage}-${added+1}.${(blob.type.split('/')[1]||'jpg').replace('jpeg','jpg')}`,blob);added++}catch{}}zip.file('manifest.json',JSON.stringify({exportedAt:new Date().toISOString(),media},null,2));const blob=await zip.generateAsync({type:'blob'});download(blob,'xe3agle-media-backup.zip');audit('MEDIA_BACKUP_EXPORTED',`${added}/${media.length} media files`);toast(added?`Media backup created: ${added} files.`:'No media could be fetched; manifest included.','success')}
async function previewImport(file){
 try{let rows=[];if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(await file.text());rows=Array.isArray(data)?data:(Array.isArray(data?.state?.trades)?data.state.trades:[])}else if(file.name.toLowerCase().endsWith('.csv'))rows=parseCSV(await file.text());else{const x=await loadXLSX();if(!x)throw new Error('XLSX library unavailable');const wb=x.read(await file.arrayBuffer(),{type:'array'});rows=x.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]]||{});}rows=rows.slice(0,5000).map(normalizeImportedTrade);const valid=rows.filter(isTradeShape),invalid=rows.length-valid.length;ensureV16().imports.lastPreview={file:file.name,count:valid.length,invalid,rows:valid};save();$('xe16-import-preview').innerHTML=`<div class="xe16-card"><strong>Import preview</strong><div class="xe16-muted">${esc(file.name)} • ${valid.length} valid • ${invalid} rejected. Nothing has been committed.</div><div style="overflow:auto;margin-top:8px"><table class="xe16-table"><thead><tr><th>Date</th><th>Direction</th><th>Entry</th><th>Result</th><th>R</th><th>Tags</th></tr></thead><tbody>${valid.slice(0,12).map(t=>`<tr><td>${esc(t.date)}</td><td>${esc(t.direction)}</td><td>${esc(t.entry)}</td><td>${esc(t.result)}</td><td>${esc(t.resultR)}</td><td>${esc((t.tags||[]).join(', '))}</td></tr>`).join('')}</tbody></table></div><button class="btn btn-primary btn-sm mt8" id="xe16-commit-import">Commit ${valid.length} trades</button></div>`;$('xe16-commit-import').onclick=()=>{const dup=duplicateCount(valid);const existing=new Set(trades().map(tradeKey));for(const t of valid){if(!existing.has(tradeKey(t))){trades().push(t);existing.add(tradeKey(t))}}save();audit('IMPORT_COMMITTED',`${valid.length} previewed; ${dup} duplicates skipped`);$('xe16-import-preview').innerHTML=`<div class="xe16-status ok">Import committed. ${valid.length-dup} added, ${dup} duplicates skipped.</div>`;window.renderAll?.();};}catch(e){$('xe16-import-preview').innerHTML=`<div class="xe16-status bad">Import rejected: ${esc(e.message||'Invalid file')}</div>`}}
function normalizeImportedTrade(t){const n=x=>{const y=Number(x);return Number.isFinite(y)?y:x};return {id:String(t.id||uid()),date:String(t.date||t.Date||new Date().toISOString().slice(0,10)).slice(0,10),time:String(t.time||t.Time||'12:00').slice(0,8),direction:String(t.direction||t.Direction||'LONG').toUpperCase(),entry:n(t.entry??t.Entry),sl:n(t.sl??t.SL),tp:n(t.tp??t.TP),rr:n(t.rr??t.RR),riskPct:n(t.riskPct??t.RiskPct),riskAmount:n(t.riskAmount??t.RiskAmount),positionSize:n(t.positionSize??t.PositionSize),setup:String(t.setup||t.Setup||''),session:String(t.session||t.Session||''),instrument:String(t.instrument||t.Instrument||''),result:String(t.result||t.Result||'BREAKEVEN').toUpperCase(),resultR:n(t.resultR??t.ResultR),resultPL:n(t.resultPL??t.PnL??t.PNL),emotion:String(t.emotion||t.Emotion||''),tags:Array.isArray(t.tags)?t.tags:String(t.tags||t.Tags||'').split(/[|,]/).map(x=>x.trim()).filter(Boolean),violations:Array.isArray(t.violations)?t.violations:String(t.violations||'').split(/[|,]/).map(x=>x.trim()).filter(Boolean),notes:String(t.notes||t.Notes||'').slice(0,4000),tradeType:'HISTORICAL'} }
function isTradeShape(t){return /^\d{4}-\d{2}-\d{2}$/.test(t.date)&&['LONG','SHORT'].includes(t.direction)&&Number.isFinite(Number(t.entry))&&Number.isFinite(Number(t.sl))&&Number.isFinite(Number(t.tp))&&['WIN','LOSS','BREAKEVEN'].includes(t.result)}
function tradeKey(t){return [isoDate(t),String(t.time||''),t.direction,Number(t.entry),Number(t.sl),Number(t.tp),String(t.setup||'')].join('|')}
function duplicateCount(arr){const seen=new Set(trades().map(tradeKey));let n=0;for(const t of arr){const k=tradeKey(t);if(seen.has(k))n++;else seen.add(k)}return n}
async function loadXLSX(){if(window.XLSX)return window.XLSX;const id='xe16-xlsx';if($(id))return new Promise(r=>$(id).addEventListener('load',()=>r(window.XLSX),{once:true}));return new Promise(r=>{const s=document.createElement('script');s.id=id;s.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';s.onload=()=>r(window.XLSX);s.onerror=()=>r(null);document.head.appendChild(s)})}
function openDialog(title,body,onSave){const w=document.createElement('div');w.className='xe16-modal';w.innerHTML=`<div><div class="flex-between"><div class="modal-title">${esc(title)}</div><button class="btn btn-sm" data-xe16-dialog-cancel>✕</button></div><div class="mt8">${body}</div><div class="btn-group mt16"><button class="btn btn-primary" data-xe16-dialog-save>Save</button><button class="btn" data-xe16-dialog-cancel>Cancel</button></div></div>`;document.body.appendChild(w);w.querySelectorAll('[data-xe16-dialog-cancel]').forEach(b=>b.onclick=()=>w.remove());w.querySelector('[data-xe16-dialog-save]').onclick=()=>{if(onSave?.()!==false)w.remove()};return w}
