function tagFields(){
 const modal=$('modal-add-trade');if(!modal||$('xe16-tags-field'))return;const anchor=$('t-session')?.closest('.field-row');const wrap=document.createElement('div');wrap.id='xe16-tags-field';wrap.className='field-row col2';wrap.innerHTML=`<div class="field"><label>Instrument</label><input id="xe16-instrument" maxlength="40" placeholder="e.g. Gold, EURUSD"></div><div class="field"><label>Tags</label><input id="xe16-tags" maxlength="300" placeholder="setup, FOMO, A+"></div>`;anchor?.insertAdjacentElement('afterend',wrap);
 const shot=$('t-screenshot')?.closest('.field');if(shot&&!$('xe16-stage-shots')){const box=document.createElement('div');box.id='xe16-stage-shots';box.className='xe16-card';box.innerHTML=`<div class="card-title">TRADE MEDIA</div><div class="xe16-muted">Upload real screenshots for each stage. Files are stored with the XE3AGLE media backend when configured.</div><div class="field-row col3"><div class="field"><label>Before</label><input id="xe16-shot-before" type="file" accept="image/*"></div><div class="field"><label>During</label><input id="xe16-shot-during" type="file" accept="image/*"></div><div class="field"><label>After</label><input id="xe16-shot-after" type="file" accept="image/*"></div></div><div id="xe16-drop" class="xe16-drop mt8">Drag & drop a screenshot here, or click to choose one<input id="xe16-drop-input" type="file" accept="image/*" hidden></div>`;shot.insertAdjacentElement('beforebegin',box);const dz=$('xe16-drop'),inp=$('xe16-drop-input');dz.onclick=()=>inp.click();['dragenter','dragover'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.add('drag')}));['dragleave','drop'].forEach(ev=>dz.addEventListener(ev,e=>{e.preventDefault();dz.classList.remove('drag')}));dz.addEventListener('drop',e=>{const f=e.dataTransfer.files?.[0];if(f&&f.type.startsWith('image/'))setFile($('t-screenshot'),f);});inp.onchange=()=>{const f=inp.files?.[0];if(f)setFile($('t-screenshot'),f)};}
}
function setFile(input,file){try{const dt=new DataTransfer();dt.items.add(file);input.files=dt.files;input.dispatchEvent(new Event('change',{bubbles:true}))}catch{toast('Browser could not attach the dropped file. Use the file picker.','error')}}
function wrapSaveTrade(){
 if(window.__xe16SaveWrapped||typeof window.saveTrade!=='function')return;const old=window.saveTrade;window.__xe16SaveWrapped=true;window.saveTrade=function(){const draft={date:$('t-date')?.value,time:$('t-time')?.value,direction:$('t-direction')?.value,entry:Number($('t-entry')?.value),sl:Number($('t-sl')?.value),tp:Number($('t-tp')?.value),setup:$('t-setup')?.value};if(!state().tradeEditId&&trades().some(t=>tradeKey(t)===tradeKey(draft))){if(!confirm('A trade with the same date, direction, entry, stop, target and setup already exists. Save anyway?'))return; audit('DUPLICATE_TRADE_OVERRIDE',tradeKey(draft));}const before=trades().length;old.apply(this,arguments);const t=state().tradeEditId?trades().find(x=>String(x.id)===String(state().tradeEditId)):trades()[trades().length-1];if(t){t.instrument=$('xe16-instrument')?.value.trim()||t.instrument||'';t.tags=($('xe16-tags')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);t.tradeType=t.tradeType||'HISTORICAL';t.media=t.media||{};const files={before:$('xe16-shot-before')?.files?.[0],during:$('xe16-shot-during')?.files?.[0],after:$('xe16-shot-after')?.files?.[0]};for(const [stage,file] of Object.entries(files))if(file)uploadMedia(file,t.id,stage).then(url=>{t.screenshots=t.screenshots||{};t.screenshots[stage]=url;t.media[stage]=url;ensureV16().media.push({tradeId:t.id,stage,url,at:new Date().toISOString()});save();}).catch(()=>toast(`Could not upload ${stage} screenshot. The trade remains saved.`,'error'));save();audit(before===trades().length?'TRADE_UPDATED':'TRADE_CREATED',String(t.id));window.renderAll?.();};};}
async function uploadMedia(file,tradeId,stage){if(!storage)throw new Error('STORAGE_UNAVAILABLE');if(!file.type.startsWith('image/'))throw new Error('IMAGE_REQUIRED');if(file.size>9*1024*1024)throw new Error('IMAGE_TOO_LARGE');const uid=AuthManager.currentUser.uid;const path=`users/${uid}/accounts/${state().accountId||'main'}/trades/${tradeId}/${stage}-${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const snap=await uploadBytes(ref(storage,path),file,{contentType:file.type,cacheControl:'private,max-age=3600'});return getDownloadURL(snap.ref)}
