function tradeDetail(id){const t=trades().find(x=>String(x.id)===String(id));if(!t)return;const shots=t.screenshots||{};const html=`<div class="xe16-modal"><div><div class="flex-between"><div class="modal-title">Trade Detail</div><button class="btn btn-sm" id="xe16-detail-close">✕</button></div><div class="xe16-grid mt12">${[['Date',isoDate(t)],['Direction',t.direction],['Setup',t.setup||t.entryModel],['Session',t.session],['Result',t.result],['R',Number(t.resultR||0).toFixed(2)],['P/L',money(t.resultPL)],['Emotion',t.emotion],['Discipline',t.discipline??'—']].map(([a,b])=>`<div class="xe16-kpi"><span class="xe16-muted">${a}</span><b>${esc(b)}</b></div>`).join('')}</div><div class="xe16-card"><strong>Tags</strong><div class="xe16-row mt8">${(t.tags||[]).map(x=>`<span class="xe16-pill">${esc(x)}</span>`).join('')||'<span class="xe16-muted">No tags</span>'}</div></div><div class="xe16-card"><strong>Notes</strong><div class="mt8">${esc(t.notes||'—').replaceAll('\n','<br>')}</div></div><div class="xe16-card"><strong>Screenshots</strong><div class="xe16-grid mt8">${['before','during','after','journal','cloud'].map(stage=>{const u=shots[stage]||t.screenshotCloudUrl||'';return u?`<div><div class="xe16-muted">${stage}</div><img src="${esc(u)}" alt="${stage}" style="width:100%;border-radius:8px;border:1px solid var(--border);margin-top:5px"></div>`:''}).join('')||'<span class="xe16-muted">No cloud screenshots.</span>'}</div></div></div></div>`;document.body.insertAdjacentHTML('beforeend',html);document.querySelector('#xe16-detail-close').onclick=e=>e.target.closest('.xe16-modal').remove()}
