function periodKey(t,kind){const d=dateOf(t);if(kind==='day')return d.toISOString().slice(0,10);if(kind==='month')return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;const x=new Date(d);const n=(x.getDay()+6)%7;x.setDate(x.getDate()-n);return x.toISOString().slice(0,10)}
function group(arr,key){const o={};for(const t of arr){const k=key(t)||'Unspecified';(o[k]??=[]).push(t)}return o}
function renderAnalytics(){const ts=closed().sort((a,b)=>dateOf(a)-dateOf(b));if(!$('xe16-analytics'))return;const wins=ts.filter(t=>t.result==='WIN').length,loss=ts.filter(t=>t.result==='LOSS').length,rs=ts.map(t=>Number(t.resultR)||0),pl=ts.reduce((a,t)=>a+(Number(t.resultPL)||0),0),avgR=rs.length?rs.reduce((a,b)=>a+b,0)/rs.length:0;const holding=ts.map(t=>Math.max(0,(new Date(t.closedAt||`${isoDate(t)}T${t.time||'12:00'}`)-new Date(t.openedAt||t.plannedAt||`${isoDate(t)}T${t.time||'12:00'}`))/60000)).filter(Number.isFinite);const avgHold=holding.length?holding.reduce((a,b)=>a+b,0)/holding.length:0;const periods=[['Daily',periodPL(periodStart('day'))],['Weekly',periodPL(periodStart('week'))],['Monthly',periodPL(periodStart('month'))]];$('xe16-kpis').innerHTML=[['Trades',ts.length],['Win rate',ts.length?(wins/ts.length*100).toFixed(1)+'%':'—'],['Total P/L',money(pl)],['Avg R',avgR.toFixed(2)+'R'],['Avg holding',avgHold?Math.round(avgHold)+' min':'—'],['Best setup',bestGroup(group(ts,t=>t.setup||t.entryModel))],['Worst setup',worstGroup(group(ts,t=>t.setup||t.entryModel))],['Long/Short',`${ts.filter(t=>t.direction==='LONG').length}/${ts.filter(t=>t.direction==='SHORT').length}`]].map(([a,b])=>`<div class="xe16-kpi"><span class="xe16-muted">${a}</span><b>${esc(b)}</b></div>`).join('');drawCurve($('xe16-equity'),ts,'equity');drawCurve($('xe16-r-curve'),ts,'r');drawCurve($('xe16-dd-curve'),ts,'dd');const table=(title,g)=>`<div class="xe16-card"><div class="card-title">${title}</div><div style="overflow:auto"><table class="xe16-table"><thead><tr><th>Group</th><th>Trades</th><th>Win%</th><th>R</th><th>P/L</th></tr></thead><tbody>${Object.entries(g).map(([k,a])=>`<tr><td>${esc(k)}</td><td>${a.length}</td><td>${(a.filter(t=>t.result==='WIN').length/a.length*100).toFixed(1)}%</td><td>${a.reduce((s,t)=>s+(Number(t.resultR)||0),0).toFixed(2)}</td><td>${esc(money(a.reduce((s,t)=>s+(Number(t.resultPL)||0),0)))}</td></tr>`).join('')||'<tr><td colspan="5">No data.</td></tr>'}</tbody></table></div></div>`;$('xe16-analytics-tables').innerHTML=periods.map(x=>`<div class="xe16-kpi"><span class="xe16-muted">${x[0]} P/L</span><b>${esc(money(x[1]))}</b></div>`).join('')+table('Daily P/L',group(ts,t=>periodKey(t,'day')))+table('Weekly P/L',group(ts,t=>periodKey(t,'week')))+table('Monthly P/L',group(ts,t=>periodKey(t,'month')))+table('By Setup',group(ts,t=>t.setup||t.entryModel))+table('By Session',group(ts,t=>t.session))+table('By Day of Week',group(ts,t=>dateOf(t).toLocaleDateString(undefined,{weekday:'long'})))+table('Long vs Short',group(ts,t=>t.direction));
 const disc=ts.map(t=>({x:Number(t.discipline)||0,y:Number(t.resultR)||0}));const high=disc.filter(x=>x.x>=80),low=disc.filter(x=>x.x<80);$('xe16-discipline-correlation').innerHTML=`<div class="xe16-grid"><div class="xe16-kpi"><span class="xe16-muted">Avg R • discipline ≥80</span><b>${high.length?(high.reduce((a,b)=>a+b.y,0)/high.length).toFixed(2):'—'}R</b></div><div class="xe16-kpi"><span class="xe16-muted">Avg R • discipline &lt;80</span><b>${low.length?(low.reduce((a,b)=>a+b.y,0)/low.length).toFixed(2):'—'}R</b></div></div>`;
 const pg=group(ts,t=>t.emotion);$('xe16-psych-correlation').innerHTML=Object.entries(pg).map(([k,a])=>`<span class="xe16-pill">${esc(k)}: ${(a.reduce((s,t)=>s+(Number(t.resultR)||0),0)/a.length).toFixed(2)}R avg • ${a.length} trades</span>`).join(' ')||'<span class="xe16-muted">Record emotions in the journal to see correlations.</span>';
}
function bestGroup(g){let best='—',v=-Infinity;for(const [k,a] of Object.entries(g)){const r=a.reduce((s,t)=>s+(Number(t.resultR)||0),0);if(r>v){v=r;best=k}}return best}
function worstGroup(g){let worst='—',v=Infinity;for(const [k,a] of Object.entries(g)){const r=a.reduce((s,t)=>s+(Number(t.resultR)||0),0);if(r<v){v=r;worst=k}}return worst}
function drawCurve(canvas,ts,kind='equity'){if(!canvas)return;const dpr=devicePixelRatio||1,w=canvas.clientWidth||600,h=canvas.clientHeight||230;canvas.width=w*dpr;canvas.height=h*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);let bal=Number(state().settings?.balance)||0,peak=bal,r=0;const vals=[kind==='equity'?bal:kind==='r'?0:0];for(const t of ts){bal+=Number(t.resultPL)||0;peak=Math.max(peak,bal);r+=Number(t.resultR)||0;vals.push(kind==='equity'?bal:kind==='r'?r:peak-bal)}const min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;c.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--green');c.lineWidth=2;c.beginPath();vals.forEach((v,i)=>{const x=12+(w-24)*(i/Math.max(1,vals.length-1)),y=12+(h-24)*(1-(v-min)/range);i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke();c.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--text3');c.font='11px sans-serif';c.fillText(kind==='equity'?'Equity curve':kind==='r'?'Cumulative R curve':'Drawdown curve',12,18)}
function discipline(){
 const page=$('page-psychology');if(!page||$('xe16-discipline'))return;const host=document.createElement('div');host.id='xe16-discipline';host.className='xe16-card';host.innerHTML=`<div class="card-title">DISCIPLINE SYSTEM</div><div id="xe16-discipline-body"></div><div class="field-row col2 mt12"><div class="field"><label>Weekly review</label><textarea id="xe16-weekly-review" placeholder="What worked, what failed, what changes next week?"></textarea></div><div class="field"><label>Monthly review</label><textarea id="xe16-monthly-review" placeholder="What does the data say about this month?"></textarea></div></div><button class="btn btn-primary btn-sm mt8" id="xe16-save-reviews">Save reviews</button><div class="mt12"><strong>Rule-override audit log</strong><div id="xe16-audit-log" class="mt8"></div></div>`;page.appendChild(host);const v=ensureV16(),ts=closed();const scored=ts.map(t=>Number(t.discipline)||0);const avg=scored.length?scored.reduce((a,b)=>a+b,0)/scored.length:0;let streak=0;for(let i=ts.length-1;i>=0;i--){const t=ts[i],viol=t.violation===1||(Array.isArray(t.violations)&&t.violations.length>0);if(!viol&&(Number(t.discipline)||0)>=80)streak++;else break}const byDay=group(ts,t=>isoDate(t));$('xe16-discipline-body').innerHTML=`<div class="xe16-grid"><div class="xe16-kpi"><span class="xe16-muted">Current discipline streak</span><b>${streak}</b></div><div class="xe16-kpi"><span class="xe16-muted">Average discipline</span><b>${avg.toFixed(1)}%</b></div><div class="xe16-kpi"><span class="xe16-muted">Days logged</span><b>${Object.keys(byDay).length}</b></div><div class="xe16-kpi"><span class="xe16-muted">Violating trades</span><b>${ts.filter(t=>t.violation===1||(t.violations||[]).length).length}</b></div></div>`;$('xe16-weekly-review').value=v.reviews.weekly.at(-1)?.text||'';$('xe16-monthly-review').value=v.reviews.monthly.at(-1)?.text||'';$('xe16-save-reviews').onclick=()=>{const at=new Date().toISOString();v.reviews.weekly.push({at,text:$('xe16-weekly-review').value.trim()});v.reviews.monthly.push({at,text:$('xe16-monthly-review').value.trim()});v.reviews.weekly=v.reviews.weekly.slice(-52);v.reviews.monthly=v.reviews.monthly.slice(-24);audit('PERIODIC_REVIEWS_SAVED');toast('Reviews saved.','success')};$('xe16-audit-log').innerHTML=(v.audit||[]).slice().reverse().slice(0,20).map(x=>`<div class="xe16-row" style="padding:5px 0;border-bottom:1px solid var(--border)"><span class="xe16-pill">${esc(x.action)}</span><span class="xe16-muted">${esc(x.at)}</span><span>${esc(x.detail)}</span></div>`).join('')||'<span class="xe16-muted">No overrides/actions logged yet.</span>';
}
function commandPalette(){
 if($('xe16-command-trigger'))return;const top=document.querySelector('.topbar-status');if(!top)return;const b=document.createElement('button');b.id='xe16-command-trigger';b.className='btn btn-sm';b.textContent='⌘ Search';b.title='Open command/search (Ctrl/Cmd+K)';top.prepend(b);const commands=[['Go to Today',()=>window.navigate?.('today')],['Go to Prepare',()=>window.navigate?.('prepare')],['Go to Journal',()=>window.navigate?.('journal')],['Go to Statistics',()=>window.navigate?.('stats')],['Go to Psychology',()=>window.navigate?.('psychology')],['Go to Settings',()=>window.navigate?.('settings')],['Export JSON',()=>$('xe16-export-json')?.click()],['Export XLSX',()=>$('xe16-export-xlsx')?.click()],['Toggle balance privacy',()=>window.toggleBalancePrivacy?.()]];const open=()=>{if($('xe16-command'))return;const w=document.createElement('div');w.id='xe16-command';w.className='xe16-command';w.innerHTML=`<div><input id="xe16-command-input" placeholder="Search commands…" autofocus><div id="xe16-command-list"></div></div>`;document.body.appendChild(w);const render=()=>{const q=$('xe16-command-input').value.toLowerCase();$('xe16-command-list').innerHTML=commands.filter(x=>x[0].toLowerCase().includes(q)).map((x,i)=>`<button data-cmd="${i}">${esc(x[0])}</button>`).join('');$('xe16-command-list').querySelectorAll('[data-cmd]').forEach(e=>e.onclick=()=>{const x=commands[Number(e.dataset.cmd)];w.remove();x[1]()})};$('xe16-command-input').oninput=render;w.onclick=e=>{if(e.target===w)w.remove()};render()};b.onclick=open;document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();open()}if(e.key==='Escape')$('xe16-command')?.remove()});}
function installErrorLogging(){if(window.__xe16Errors)return;window.__xe16Errors=true;const clean=x=>String(x||'').replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g,'[email]').replace(/(password|token|apiKey|secret)=?[^&\s]*/gi,'[redacted]').slice(0,500);const log=(type,value)=>{try{const v=ensureV16();v.audit.push({id:uid(),at:new Date().toISOString(),action:'CLIENT_ERROR',detail:clean(type+': '+value)});v.audit=v.audit.slice(-1000);save()}catch{}};window.addEventListener('error',e=>log('error',e.message||'unknown'));window.addEventListener('unhandledrejection',e=>log('promise',e.reason?.message||e.reason||'unknown'))}
function offlineStatus(){const render=()=>{let el=$('xe16-online-status');if(!el){el=document.createElement('span');el.id='xe16-online-status';el.className='xe16-status';document.querySelector('.topbar-status')?.prepend(el)}const online=navigator.onLine;const sync=state().sync||{};el.className='xe16-status '+(online?'ok':'warn');const when=Number(sync.lastSyncedAt)?new Date(Number(sync.lastSyncedAt)).toLocaleTimeString():'';el.textContent=online?(when?'ONLINE • SYNC '+when:'ONLINE • LOCAL'):'OFFLINE • LOCAL';};window.addEventListener('online',render);window.addEventListener('offline',render);setInterval(render,5000);render()}
function installDeleteOverride(){
 const old=window.confirmDeleteAll;if(typeof old!=='function'||old.__xe16)return;const wrapped=async function(){if($('delete-confirm-input')?.value!=='DELETE'){toast('Type DELETE to confirm.','error');return}if(!confirm('This permanently deletes your cloud account data and XE3AGLE account. Continue?'))return;try{await deleteAllCloud();toast('Account and cloud data deleted.','success');location.reload()}catch(e){toast('Deletion failed before completion. No success was reported.','error')}};wrapped.__xe16=true;window.confirmDeleteAll=wrapped;
}
function installProtectionMonitor(){
 const check=()=>{const p=protection(),s=state();const hit=(p.limits.daily>0&&p.daily>=p.limits.daily)||(p.limits.weekly>0&&p.weekly>=p.limits.weekly)||(p.limits.monthly>0&&p.monthly>=p.limits.monthly)||(p.limits.trailing>0&&p.trailing>=p.limits.trailing)||(p.limits.profitTarget>0&&p.profit>=p.limits.profitTarget);if(hit&&!s.activeTrade&&!s.killSwitch){const reason=p.limits.profitTarget>0&&p.profit>=p.limits.profitTarget?'Profit target reached.':'Account protection limit reached.';s.killSwitch=true;s.killReason=reason;s.workflowStage='terminated';audit('AUTO_SESSION_TERMINATED',reason);toast('SESSION TERMINATED — '+reason,'error');save();window.renderAll?.();window.renderAllV10?.();}};check();setInterval(check,30000)}
